#!/usr/bin/env python3
"""Regenerate docs/04_station_kernel.md from scripts/station_kernel.py (full listing + annotations).

usage: python3 -I tools/gen_kernel_listing.py [--check]
--check exits 1 if docs/04 is out of date (tests/test_docs_sync.py runs this).
"""
import os
import sys

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
SRC = os.path.join(ROOT, 'scripts', 'station_kernel.py')
DOC = os.path.join(ROOT, 'docs', '04_station_kernel.md')

HEADER = """# 04 - The station kernel, annotated

<!-- GENERATED by tools/gen_kernel_listing.py from scripts/station_kernel.py. Edit those, then regenerate. -->

`scripts/station_kernel.py` is a plain Python **script kernel**, run top to bottom as a batch job. This page is
the complete source, cut into segments, with notes after each one. The concatenated code blocks are byte-identical
to the script (`tests/test_docs_sync.py` checks this).

## Pipeline and measured timeline

| Step | Function / section | Measured in the reference run (t from first log line) |
|---|---|---|
| 1 credentials | `credential()` | 0 s |
| 2 unpack kit | `zstd_stream_reader()` + `tarfile` | 500 MB archive in 14 s; all kit archives by +36 s (including pip installs, 11 s) |
| 3 setup shell, env probe | `SETUP_SHELL`, `ENV_PROBE` | included above |
| 4 gate | `GATE_CMD` | finished at +3 min 27 s: 156 items, 0 differences, 170 s with 2 parallel jobs |
| 5 install + probe | `INSTALL_CMD`, `PROBE_CMD` | 23 s, at +3 min 50 s |
| 6 workers | `subprocess.Popen` | 5 workers 20 s apart, all running by +5 min 10 s |
| 7 control loop | `apply_control()`, `soft_stop_due()` | every `LOOP_S` (the measured kernel used 60 s) |
| 8 results | `pack_results()` | seconds |

The reference run used the project-specific predecessor of this file. The timings carry over because the steps
are the same. The template itself was run end to end on Kaggle on 2026-11-22 (30-minute test, one shell worker
and one Claude Code worker, a 4 KB kit, no gate): credentials and kit at +3 s, env probe at +4 s, install 10 s,
probe OK at +19 s, both workers started by +39 s, control dataset version applied 36 s after publishing,
deadline kill to `done` in 34 s (MEASURED).

## CONFIG reference

| Setting | Default | Meaning |
|---|---|---|
| `RUN_HOURS` | 3.0 | initial deadline = start + this; the control file can move it |
| `MAX_HOURS` | 11.0 | hard cap for the deadline and the per-worker `timeout`; keep it below the platform limit minus about 15 min |
| `SOFT_STOP_LEAD_MIN` | 20 | default soft stop = deadline - this |
| `KILL_GRACE_S` | 90 | SIGTERM, then SIGKILL after this |
| `LOOP_S` | 30 | control loop period |
| `INPUT_ROOT` | `/kaggle/input` | where datasets are mounted |
| `WORKDIR` | `/home/station/project` | unpack target; not under `/kaggle/working` |
| `KIT_ARCHIVES` | `['kit_base.tar.zst', 'kit_work.tar.zst']` | file names searched under `INPUT_ROOT`, unpacked in order |
| `REMOVE_AFTER_UNPACK` | `[]` | e.g. a copied virtualenv |
| `PATH_LINKS` | `{}` | absolute reference-machine paths to symlink into `WORKDIR` |
| `SETUP_SHELL` | `true` | bash script (`set -e`) run in `WORKDIR` |
| `ENV_PROBE` | `command -v python3; ...` | logged diagnostics |
| `REQUIRED_CREDENTIALS` | `['CLAUDE_CODE_OAUTH_TOKEN']` | exit if missing |
| `OPTIONAL_CREDENTIALS` | `['PROJECT_API_KEY', 'KAGGLE_JSON']` | - |
| `WORKER_ENV_CREDENTIALS` | `['CLAUDE_CODE_OAUTH_TOKEN']` | put in worker environments |
| `FILE_CREDENTIALS` | `{'PROJECT_API_KEY': '/root/.config/project/api_key'}` | written 0600 |
| `DROP_ENV_PREFIXES` | Kaggle session token names | removed from worker environments |
| `GATE_CMD`, `GATE_REFERENCE`, `GATE_OUTPUT`, `GATE_FIELD`, `GATE_TIMEOUT_S` | see docs/07 | `GATE_CMD = None` skips the gate |
| `INSTALL_CMD` | Claude Code native installer | `None` if the tool is in the kit or image |
| `EXTRA_PATH` | `['/root/.local/bin']` | prepended to workers' `PATH` |
| `PROBE_CMD`, `PROBE_EXPECT` | one-shot `claude -p`, `OK` | `None` skips |
| `WORKER_CMD` | Claude Code preset (docs/05) | tokens `{NAME} {ASSIGNMENT} {BRIEF} {BRIEF_FILE} {WORKDIR}` |
| `WORKERS` | 4 example workers | name -> assignment |
| `WORKER_STAGGER_S` | 20 | delay between worker starts |
| `BRIEF_TEMPLATE` | generic brief | must state the INBOX / STOP / STATUS / REPORT conventions |
| `CONTROL_FILE` | `station_control.json` | name searched under `INPUT_ROOT` at start |
| `CONTROL_DATASET`, `CONTROL_POLL_S` | `None`, 300 | live control (MEASURED channel, docs/06) |
| `OUTBOX_DATASET`, `OUTBOX_EVERY_S` | `None`, 1800 | progress dataset (MEASURED channel, docs/06) |
| `STDOUT_PROGRESS_S` | 300 | `STATION {...}` lines |
| `RELAY_TARGET` | `None` | appendix A |
| `OUT` | `/kaggle/working/out` | run output folder |
| `PRIVATE_DIR` | `/root/.station` | station scratch, never in the output |
| `RESULT_GLOBS`, `RESULT_SUFFIXES`, `RESULT_EXCLUDE_GLOBS`, `RESULT_MAX_FILE_BYTES`, `RESULT_ONLY_NEW_OR_CHANGED` | see docs/03 | results allow-list |
| `SNAPSHOT_EVERY_S` | 1800 | periodic `results.tar.gz` |

## Full listing
"""

# (first line of the segment, heading, notes)
SEGMENTS = [
    ('#!/usr/bin/env python3', 'Header and imports', [
        'Standard library only. The `zstandard` module is imported lazily in `zstd_stream_reader()`.',
        'The header comment states the contract: change only CONFIG; changeable values live in the control file.']),
    ('# ======', 'CONFIG', [
        'Nothing here is secret. Credentials are referenced by name only.',
        '`MAX_HOURS` is the only time that can never change after start. Make it generous and steer with the control file.',
        '`SETUP_SHELL` runs with `/bin/bash` and `set -e`. The measured run lost an attempt to `/bin/sh` lacking `source` (docs/10 #3).',
        '`WORKER_CMD` can be any program. The Claude Code preset is the measured worker command. One command for mixed workers (shell and Claude Code in one run): docs/05.',
        '`RESULT_ONLY_NEW_OR_CHANGED` is what keeps toolchain and target data out of `results.tar.gz`.']),
    ('UTC = dt.timezone.utc', 'State and helpers: time, log, shell, inputs, credentials', [
        '`STATE` holds everything the control file can change, plus delivered message ids (in memory, so per run).',
        "`sh()` always uses `executable='/bin/bash'` and turns a timeout into rc 124 instead of an exception.",
        '`find_input()` searches by file name at any depth, because mount paths vary (MEASURED: two layouts in one session).',
        '`credential()` tries a file first (keys dataset, works for CLI pushes), then a Kaggle Secret (editor runs only). It never logs a value.']),
    ('def apply_control(', 'The control protocol', [
        'Unit-tested in `tests/test_station_kernel.py` (stale seq, cap, soft stop follows deadline, stop_all lift, once-per-id delivery).',
        'Lifting only removes STOP files whose content starts with `station`, so a STOP written by a worker or by you survives.',
        '`read_control_file()` accepts a plain file or a zip, because `kaggle datasets download -f` may return either.']),
    ('def manifest(', 'Results allow-list and packing', [
        '`manifest()` records (size, mtime_ns) of every kit file after setup. Unchanged kit files are never packed.',
        'Symlinks are skipped, so a link into the toolchain cannot smuggle it out.',
        'Packing writes `.part` and renames it, so the archive is always complete.']),
    ('def kaggle_env(', 'Kaggle-native channels and the optional relay', [
        'Without `KAGGLE_JSON` the station relies on the session\'s built-in Kaggle login (MEASURED: `kernels list`, `datasets download` and `datasets version` all worked with it in the 2026-11-22 template run; `KAGGLE_JSON` was not needed).',
        'Every network call has a subprocess timeout and `check=False`: a failing channel is logged and the run continues.',
        '`push_outbox()` uses `-d` to delete old outbox versions, so the outbox does not grow without bound.']),
    ('def status_doc(', 'Status, process control, zstd, token filling', [
        '`kill_group()` signals the whole process group, which reaches the agent\'s background tasks too, unless they started their own session.',
        '`zstd_stream_reader()`: Python 3.14 has `compression.zstd`; Kaggle\'s 3.13 has the `zstandard` module (MEASURED); otherwise pip installs it.']),
    ('def main():', 'main(): steps 1 to 3 (credentials, kit, gate)', [
        'Credential names, never values, go to `setup.log`.',
        '`tarfile` `filter=\'tar\'` keeps permissions and symlinks that toolchains need, and blocks absolute and `..` paths.',
        'The gate fails closed: any difference, missing item, empty reference or unreadable file means exit 1 and no workers.']),
    ('    # 4. worker tool', 'main(): steps 4 and 5 (install, probe, workers)', [
        'Worker environment = session environment minus Kaggle tokens, plus `EXTRA_PATH` and the listed credentials.',
        'The control file attached at start is applied before workers start, so a pre-set deadline or message is in place from the first minute.',
        'Each worker: `timeout -k 30 <cap_s>`, its own session (process group), its own log file in `out/logs/`.']),
    ('    # 6. control loop', 'main(): step 6, the control loop', [
        'Order per pass: fetch control, apply, soft stop, deadline kill, status.json, STATION line, outbox, snapshot.',
        'The loop ends when no worker is alive, after normal completion or after the deadline kill.']),
    ('    # 7. results', 'main(): step 7 (results) and entry point', [
        'The final `status.json` carries `"final": true`. If it is missing, the container died before this point.',
        "`if __name__ != 'station_kernel'` runs `main()` when Kaggle executes the file, but not when the tests import it under that name."]),
]


def build():
    with open(SRC) as f:
        lines = f.read().split('\n')
    starts = []
    for first, _, _ in SEGMENTS:
        idx = next(i for i, ln in enumerate(lines) if ln.startswith(first) and all(i > s for s in starts))
        starts.append(idx)
    starts.append(len(lines))
    out = [HEADER]
    for k, (_, heading, notes) in enumerate(SEGMENTS):
        chunk = lines[starts[k]:starts[k + 1]]
        if k == len(SEGMENTS) - 1 and chunk and chunk[-1] == '':
            chunk = chunk[:-1]
        out.append('### %d. %s\n\n```python\n%s\n```\n' % (k + 1, heading, '\n'.join(chunk)))
        out.append(''.join('- %s\n' % n for n in notes))
    return '\n'.join(out)


if __name__ == '__main__':
    text = build()
    if '--check' in sys.argv:
        with open(DOC) as f:
            sys.exit(0 if f.read() == text else 'docs/04 is out of date: run python3 -I tools/gen_kernel_listing.py')
    with open(DOC, 'w') as f:
        f.write(text)
    print('wrote', DOC)
